const CACHE_KEY="incredible-india-ai-translation-cache",CACHE_LIMIT=500;function loadCache(){try{return"undefined"==typeof localStorage?{}:JSON.parse(localStorage.getItem(CACHE_KEY)||"{}")}catch{return{}}}function saveCache(t){try{if("undefined"==typeof localStorage)return;const e=Object.keys(t);if(e.length>500)for(const n of e.slice(0,e.length-500))delete t[n];localStorage.setItem(CACHE_KEY,JSON.stringify(t))}catch{}}function cacheKeyFor(t,e){let n=0;for(let e=0;e<t.length;e++)n=31*n+t.charCodeAt(e)|0;return`${e}:${n}`}export class TranslationClient{constructor(t={}){this.endpoint=t.endpoint||"/frontend/api/translate",this.fetchImpl=t.fetchImpl||("undefined"!=typeof fetch?fetch.bind(globalThis):null),this.cache=loadCache(),this.pending=new Map}async translate(t,e,{sourceLang:n="en",context:a}={}){if(!t||e===n)return{text:t,source:"skip",targetLang:e};const r=cacheKeyFor(t,e);if(this.cache[r]&&this.cache[r].original===t)return{text:this.cache[r].translated,source:"cache",targetLang:e};if(this.pending.has(r))return this.pending.get(r);const i=this._request(t,e,n,a).then(n=>(this.cache[r]={original:t,translated:n},saveCache(this.cache),{text:n,source:"ai",targetLang:e})).catch(()=>({text:t,source:"error",targetLang:e})).finally(()=>this.pending.delete(r));return this.pending.set(r,i),i}async _request(t,e,n,a){if(!this.fetchImpl)throw new Error("fetch is not available in this environment");const r=await this.fetchImpl(this.endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({text:t,targetLang:e,sourceLang:n,context:a})});if(!r.ok)throw new Error(`Translation request failed: ${r.status}`);const i=await r.json();if(!i||"string"!=typeof i.translatedText)throw new Error("Malformed translation response");return i.translatedText}}export default TranslationClient;